def is_palindromic(arr):
    return arr == arr[::-1]

def smallest_change(arr):
    if is_palindromic(arr):
        return 0

    count = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            count += 1
        left += 1
        right -= 1

    return count

